# Exact DP enumeration of 9-step upward paths on an 8-column x 10-row board.
# Rows 0..9 (row 0 = bottom, row 9 = top); columns 0..7.
# Each step goes up exactly one row to a column differing by at most 1.
# Landing squares must be white. Both chess colorings are checked because
# the problem does not fix which corner is white.

COLS, ROWS, STEPS = 8, 10, 9
CLAIMED = 255

def white(r, c, parity):
    return (r + c) % 2 == parity

def paths_from(pcol, parity):
    """Return dict: top-row column -> number of valid 9-step paths from (0,pcol)."""
    ways = {pcol: 1}
    for r in range(1, ROWS):
        nxt = {}
        for c, w in ways.items():
            for dc in (-1, 0, 1):
                nc = c + dc
                if 0 <= nc < COLS and white(r, nc, parity):
                    nxt[nc] = nxt.get(nc, 0) + w
        ways = nxt
    return ways

same_col_values = set()
print("Same-column reading (Q directly above P, top row):")
for parity in (0, 1):
