        if not white(1, pcol, parity) and not white(1, pcol, parity):
            pass
        ends = paths_from(pcol, parity)
        n = ends.get(pcol, 0)
        same_col_values.add(n)
        print(f"  {label}, P col {pcol}: paths to Q in same column = {n}")

print("Distinct same-column counts:", sorted(same_col_values))
print(f"Claimed answer: {CLAIMED}")
if CLAIMED in same_col_values:
    print("CHECK PASS: claimed value is attained by an exhaustive enumeration.")
else:
